def orderlyQueue(S, K):
    if K == 1:
        min_rotation = S
        for i in range(len(S)):
            rotated = S[i:] + S[:i]
            if rotated < min_rotation:
                min_rotation = rotated
        return min_rotation
    else:
        return ''.join(sorted(S))

